def test_positive_score():
    assert solution.neuron([1, -1], [2, -3], 1) == 6.0

def test_negative_score():
    assert solution.neuron([-2, 1], [2, -3], 1) == 0.0

def test_bias_lifts():
    assert solution.neuron([-1], [1], 2) == 1.0

def test_zero_score():
    assert solution.neuron([0, 0], [5, -4], 0) == 0.0

def test_length_mismatch():
    try:
        solution.neuron([1, 2], [1], 0)
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_returns_float():
    assert isinstance(solution.neuron([1], [2], 0), float)
